div.script:
(function(){
  var txt=document.getElementById('qo-text'), go=document.getElementById('qo-review'),
      out=document.getElementById('qo-out'), csrf=document.getElementById('qo-csrf').value;
  var lines=[];
  function el(tag,cls,text){var e=document.createElement(tag); if(cls){e.className=cls;} if(text!==undefined){e.textContent=text;} return e;}
  function money(n){return '$'+Number(n).toFixed(2);}
  function current(l){
    if(l.skip||l.pick===null){return null;}
    var o=l.options[l.pick];
    return (o&&!o.variants)?o:null;
  }
  function render(){
    out.textContent='';
    if(!lines.length){return;}
    var list=el('div','qo-list'), total=0, ready=0, pending=0, missing=0;
    lines.forEach(function(l){
      var row=el('div','qo-row'+(l.skip?' skip':''));
      var left=el('div','qo-left');
      left.appendChild(el('div','qo-raw',l.raw));
      if(l.fuzzy){left.appendChild(el('div','qo-note','Buscado como «'+l.fuzzy+'»'));}
      row.appendChild(left);
      var mid=el('div','qo-mid');
      if(l.status==='missing'){
        mid.appendChild(el('span','qo-chip bad','No encontrado'));
        if(!l.skip){missing++;}
      } else {
        if(l.options.length>1){
          var sel=el('select','qo-sel');
          var ph=el('option',null,'Elige el producto…'); ph.value=''; sel.appendChild(ph);
          l.options.forEach(function(o,k){
            var op=el('option',null,o.name+' — '+money(o.price)); op.value=String(k);
            if(l.pick===k){op.selected=true;}
            sel.appendChild(op);
          });
          sel.addEventListener('change',function(){l.pick=(sel.value===''?null:parseInt(sel.value,10)); render();});
          mid.appendChild(sel);
        }
        var o=(l.pick===null)?null:l.options[l.pick];
        if(o){
          var prod=el('div','qo-prod'), img=el('img'); img.src=o.image; img.alt=''; prod.appendChild(img);
          var info=el('div'); info.appendChild(el('div','qo-pname',o.name));
          var pr=el('div','qo-price');
          if(o.variants){
            var a=el('a',null,'Tiene variantes: ábrelo en la tienda'); a.href=o.url; pr.appendChild(a);
          } else { pr.textContent=money(o.price)+' c/u'; }
          info.appendChild(pr); prod.appendChild(info); mid.appendChild(prod);
        }
        if(!l.skip){
          var cur=current(l);
          if(cur){ready++; total+=cur.price*l.qty;} else {pending++;}
        }
      }
      row.appendChild(mid);
      var qty=el('input','qo-qty'); qty.type='number'; qty.min='1'; qty.max='9999'; qty.value=l.qty;
      qty.setAttribute('aria-label','Cantidad');
      qty.addEventListener('change',function(){var v=parseInt(qty.value,10); l.qty=(v>0?v:1); render();});
      row.appendChild(qty);
      var x=el('button','qo-x',l.skip?'↺':'×'); x.type='button';
      x.setAttribute('aria-label',l.skip?'Volver a incluir':'Quitar línea');
      x.addEventListener('click',function(){l.skip=!l.skip; render();});
      row.appendChild(x);
      list.appendChild(row);
    });
    out.appendChild(list);
    var sum=el('div','qo-sum'), st=el('div','qo-sumtxt');
    st.appendChild(el('div',null,ready+' listas'+(pending?' · '+pending+' por elegir':'')+(missing?' · '+missing+' no encontradas':'')));
    st.appendChild(el('div','qo-total',money(total)));
    sum.appendChild(st);
    var add=el('button','qo-btn','Agregar al carrito'); add.type='button'; add.disabled=(ready===0);
    add.addEventListener('click',function(){addAll(add);});
    sum.appendChild(add);
    out.appendChild(sum);
  }
  function addAll(btn){
    var items=[];
    lines.forEach(function(l){var o=current(l); if(o){items.push({template_id:o.template_id,qty:l.qty,name:o.name});}});
    if(!items.length){return;}
    btn.disabled=true; btn.textContent='Agregando…';
    var fd=new FormData(); fd.append('csrf_token',csrf); fd.append('items',JSON.stringify(items));
    fetch('/pedido-rapido/agregar',{method:'POST',body:fd,credentials:'same-origin'})
      .then(function(r){return r.json();})
      .then(function(d){
        if(d.skipped&&d.skipped.length){alert('No se pudieron agregar: '+d.skipped.join(', '));}
        window.location.href='/shop/cart';
      })
      .catch(function(){btn.disabled=false; btn.textContent='Agregar al carrito'; alert('No se pudo agregar al carrito. Intenta de nuevo.');});
  }
  go.addEventListener('click',function(){
    var t=txt.value.trim();
    if(!t){txt.focus(); return;}
    go.disabled=true; go.textContent='Revisando…';
    var fd=new FormData(); fd.append('csrf_token',csrf); fd.append('texto',t);
    fetch('/pedido-rapido/revisar',{method:'POST',body:fd,credentials:'same-origin'})
      .then(function(r){return r.json();})
      .then(function(d){
        lines=d.lines.map(function(l){l.skip=false; l.pick=(l.status==='ok')?0:null; return l;});
        go.disabled=false; go.textContent='Revisar de nuevo';
        render();
        if(d.truncated){alert('Solo se revisaron las primeras 200 líneas.');}
      })
      .catch(function(){go.disabled=false; go.textContent='Revisar pedido'; alert('No se pudo revisar la lista. Intenta de nuevo.');});
  });
})();
